mapper.update:
UPDATE async_task_record
SET worker_id = #{workerId},
    last_heartbeat_at = #{heartbeatAt},
    updated_at = #{heartbeatAt}
WHERE task_id = #{taskId}
  AND status = 'RUNNING'

mapper.select:
SELECT 
FROM async_task_record
WHERE (
        status = 'CREATED'
        AND created_at <= #{heartbeatBefore}
      )
   OR (
        status = 'RUNNING'
        AND (last_heartbeat_at IS NULL OR last_heartbeat_at <= #{heartbeatBefore})
      )
ORDER BY id ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM async_task_record
WHERE status IN ('SUCCESS', 'FAILED', 'CANCELED', 'EXPIRED')
  AND updated_at <= #{updatedBefore}
ORDER BY id ASC
LIMIT #{limit}
